type NameStep interface  { Name(string) EmailStep }
type EmailStep interface { Email(string) BuildStep }
type BuildStep interface { Build() (*User, error) }

func NewUserBuilder() NameStep { return &builder{} }

type builder struct{ name, email string }

func (b *builder) Name(n string) EmailStep  { b.name = n; return b }
func (b *builder) Email(e string) BuildStep { b.email = e; return b }
func (b *builder) Build() (*User, error)    { return &User{Name: b.name, Email: b.email}, nil }
